@@ -0,0 +1,60 @@
+const defaultTextFields = ["name", "title", "label", "description", "type", "category", "kind"];
+
+function normalize(value) {
+  return String(value ?? "")
+    .normalize("NFD")
+    .replace(/\p{Diacritic}/gu, "")
+    .toLocaleLowerCase("es-AR");
+}
+
+function itemMatchesQuery(item, query, fields = defaultTextFields) {
+  if (!query) return true;
+  const normalizedQuery = normalize(query);
+  return fields.some((field) => normalize(item?.[field]).includes(normalizedQuery));
+}
+
+function itemMatchesFilters(item, filters = {}) {
+  return Object.entries(filters).every(([field, expected]) => {
+    if (expected == null || expected === "") return true;
+    const actual = item?.[field];
+
+    if (Array.isArray(expected)) {
+      return expected.some((candidate) => normalize(candidate) === normalize(actual));
+    }
+
+    if (typeof expected === "function") {
+      return Boolean(expected(actual, item));
+    }
+
+    return normalize(actual) === normalize(expected);
+  });
+}
+
+export function exploreRoute(items = [], options = {}) {
+  const { query = "", filters = {}, fields = defaultTextFields } = options;
+  return items.filter((item) => itemMatchesQuery(item, query, fields) && itemMatchesFilters(item, filters));
+}
+
+export function filterRouteExploration(items = [], filters = {}) {
+  return exploreRoute(items, { filters });
+}
+
+export function searchRouteExploration(items = [], query = "", fields = defaultTextFields) {
+  return exploreRoute(items, { query, fields });
+}
+
+export function createRouteExplorer({ fields = defaultTextFields } = {}) {
+  return {
+    explore(items = [], options = {}) {
+      return exploreRoute(items, { ...options, fields: options.fields ?? fields });
+    },
+    filter(items = [], filters = {}) {
+      return exploreRoute(items, { filters, fields });
+    },
+    search(items = [], query = "") {
+      return exploreRoute(items, { query, fields });
+    }
+  };
+}
+
+export default exploreRoute;
