+const DEFAULT_KEY_FIELDS = ["id", "slug", "key"];
+
+function isObject(value) {
+  return value !== null && typeof value === "object";
+}
+
+function cloneFavorite(value) {
+  if (Array.isArray(value)) {
+    return value.slice();
+  }
+
+  if (isObject(value)) {
+    return { ...value };
+  }
+
+  return value;
+}
+
+function getFavoriteKey(value) {
+  if (value === null || value === undefined) {
+    throw new TypeError("A favorite must be a non-null value.");
+  }
+
+  if (isObject(value)) {
+    for (const field of DEFAULT_KEY_FIELDS) {
+      if (field in value && value[field] !== undefined && value[field] !== null) {
+        return `${field}:${String(value[field])}`;
+      }
+    }
+
+    return `json:${JSON.stringify(value)}`;
+  }
+
+  return `${typeof value}:${String(value)}`;
+}
+
+export class FavoritesStore {
+  #favorites = new Map();
+
+  constructor(keyOf = getFavoriteKey) {
+    this.keyOf = keyOf;
+  }
+
+  mark(favorite) {
+    const key = this.keyOf(favorite);
+    if (!this.#favorites.has(key)) {
+      this.#favorites.set(key, cloneFavorite(favorite));
+    }
+
+    return this.list();
+  }
+
+  unmark(favorite) {
+    const key = this.keyOf(favorite);
+    this.#favorites.delete(key);
+
+    return this.list();
+  }
+
+  list() {
+    return Array.from(this.#favorites.values(), cloneFavorite);
+  }
+
+  clear() {
+    this.#favorites.clear();
+    return this.list();
+  }
+
+  has(favorite) {
+    return this.#favorites.has(this.keyOf(favorite));
+  }
+}
+
+export const favorites = new FavoritesStore();
+
+export function markFavorite(favorite) {
+  return favorites.mark(favorite);
+}
+
+export function unmarkFavorite(favorite) {
+  return favorites.unmark(favorite);
+}
+
+export function listFavorites() {
+  return favorites.list();
+}
+
+export function clearFavorites() {
+  return favorites.clear();
+}
+
+export function hasFavorite(favorite) {
+  return favorites.has(favorite);
+}
+
+export default {
+  FavoritesStore,
+  favorites,
+  markFavorite,
+  unmarkFavorite,
+  listFavorites,
+  clearFavorites,
+  hasFavorite
+};
