+const PACKING_FILTERS = Object.freeze({
+  all: "all",
+  completed: "completed",
+  pending: "pending",
+});
+
+function createId() {
+  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `packing-${Math.random().toString(36).slice(2, 10)}`;
+}
+
+function normalizeLabel(label) {
+  if (typeof label !== "string") {
+    throw new TypeError("Packing item label must be a string.");
+  }
+
+  const trimmed = label.trim();
+  if (trimmed.length === 0) {
+    throw new RangeError("Packing item label cannot be empty.");
+  }
+
+  return trimmed;
+}
+
+function normalizeItem(item) {
+  if (!item || typeof item !== "object") {
+    throw new TypeError("Packing item must be an object.");
+  }
+
+  const label = normalizeLabel(item.label);
+
+  return {
+    id: typeof item.id === "string" && item.id.trim() ? item.id : createId(),
+    label,
+    packed: Boolean(item.packed),
+  };
+}
+
+function normalizeChecklist(checklist) {
+  if (!checklist || typeof checklist !== "object") {
+    throw new TypeError("Packing checklist must be an object.");
+  }
+
+  const items = Array.isArray(checklist.items) ? checklist.items.map(normalizeItem) : [];
+  const filter = Object.values(PACKING_FILTERS).includes(checklist.filter)
+    ? checklist.filter
+    : PACKING_FILTERS.all;
+
+  return {
+    items,
+    filter,
+  };
+}
+
+function mapItemById(items, id, updater) {
+  let found = false;
+
+  const nextItems = items.map((item) => {
+    if (item.id !== id) {
+      return item;
+    }
+
+    found = true;
+    return updater(item);
+  });
+
+  if (!found) {
+    throw new RangeError(`Packing item not found: ${id}`);
+  }
+
+  return nextItems;
+}
+
+export function createPackingChecklist(items = []) {
+  if (!Array.isArray(items)) {
+    throw new TypeError("Packing checklist items must be an array.");
+  }
+
+  return normalizeChecklist({
+    items,
+    filter: PACKING_FILTERS.all,
+  });
+}
+
+export function addPackingItem(checklist, item) {
+  const nextChecklist = normalizeChecklist(checklist);
+  const nextItem = normalizeItem(item);
+
+  return {
+    ...nextChecklist,
+    items: [...nextChecklist.items, nextItem],
+  };
+}
+
+export function completePackingItem(checklist, id, packed = true) {
+  const nextChecklist = normalizeChecklist(checklist);
+
+  return {
+    ...nextChecklist,
+    items: mapItemById(nextChecklist.items, id, (item) => ({
+      ...item,
+      packed: Boolean(packed),
+    })),
+  };
+}
+
+export function togglePackingItem(checklist, id) {
+  const nextChecklist = normalizeChecklist(checklist);
+
+  return {
+    ...nextChecklist,
+    items: mapItemById(nextChecklist.items, id, (item) => ({
+      ...item,
+      packed: !item.packed,
+    })),
+  };
+}
+
+export function setPackingFilter(checklist, filter) {
+  const nextChecklist = normalizeChecklist(checklist);
+  const nextFilter = Object.values(PACKING_FILTERS).includes(filter) ? filter : PACKING_FILTERS.all;
+
+  return {
+    ...nextChecklist,
+    filter: nextFilter,
+  };
+}
+
+export function filterPackingItems(checklist, filter = checklist?.filter ?? PACKING_FILTERS.all) {
+  const nextChecklist = normalizeChecklist(checklist);
+  const nextFilter = Object.values(PACKING_FILTERS).includes(filter) ? filter : PACKING_FILTERS.all;
+
+  if (nextFilter === PACKING_FILTERS.completed) {
+    return nextChecklist.items.filter((item) => item.packed);
+  }
+
+  if (nextFilter === PACKING_FILTERS.pending) {
+    return nextChecklist.items.filter((item) => !item.packed);
+  }
+
+  return [...nextChecklist.items];
+}
+
+export function getPackingItems(checklist) {
