@@ -0,0 +1,261 @@
+const CATEGORY_INPUT_ERROR = "category must be a non-empty string";
+
+function normalizeCategory(category) {
+  if (typeof category !== "string") {
+    throw new TypeError(CATEGORY_INPUT_ERROR);
+  }
+
+  const normalized = category.trim();
+  if (!normalized) {
+    throw new TypeError(CATEGORY_INPUT_ERROR);
+  }
+
+  return normalized;
+}
+
+function normalizeAmount(amount, label = "amount") {
+  if (typeof amount !== "number" || !Number.isFinite(amount)) {
+    throw new TypeError(`${label} must be a finite number`);
+  }
+
+  return amount;
+}
+
+function normalizeExpenseList(expenses) {
+  if (!Array.isArray(expenses)) {
+    return [normalizeAmount(expenses, "expense")];
+  }
+
+  return expenses.map((expense) => {
+    if (expense && typeof expense === "object" && "amount" in expense) {
+      return normalizeAmount(expense.amount, "expense.amount");
+    }
+
+    return normalizeAmount(expense, "expense");
+  });
+}
+
+function normalizeCategoryEntry(category, value) {
+  const normalizedCategory = normalizeCategory(category);
+
+  if (value && typeof value === "object" && !Array.isArray(value)) {
+    const budget = "budget" in value ? normalizeAmount(value.budget, "budget") : 0;
+    const expenses = "expenses" in value ? normalizeExpenseList(value.expenses) : [];
+
+    return {
+      category: normalizedCategory,
+      budget,
+      expenses,
+    };
+  }
+
+  return {
+    category: normalizedCategory,
+    budget: normalizeAmount(value, "budget"),
+    expenses: [],
+  };
+}
+
+function summarizeCategory(category, record) {
+  const spent = record.expenses.reduce((total, expense) => total + expense, 0);
+  const available = record.budget - spent;
+
+  return {
+    category,
+    budget: record.budget,
+    spent,
+    available,
+  };
+}
+
+export class Budget {
+  #total;
+  #categories;
+
+  constructor(initialValue = 0) {
+    this.#total = 0;
+    this.#categories = new Map();
+
+    if (typeof initialValue === "number") {
+      this.setTotal(initialValue);
+      return;
+    }
+
+    if (initialValue && typeof initialValue === "object") {
+      if ("total" in initialValue) {
+        this.setTotal(initialValue.total);
+      }
+
+      if ("categories" in initialValue) {
+        this.loadCategories(initialValue.categories);
+      }
+
+      if ("expensesByCategory" in initialValue) {
+        this.loadExpensesByCategory(initialValue.expensesByCategory);
+      }
+    }
+  }
+
+  setTotal(total) {
+    this.#total = normalizeAmount(total, "total");
+    return this;
+  }
+
+  setCategoryBudget(category, budget) {
+    const normalizedCategory = normalizeCategory(category);
+    const record = this.#categories.get(normalizedCategory) ?? {
+      budget: 0,
+      expenses: [],
+    };
+
+    record.budget = normalizeAmount(budget, "budget");
+    this.#categories.set(normalizedCategory, record);
+    return this;
+  }
+
+  addExpense(category, amount) {
+    const normalizedCategory = normalizeCategory(category);
+    const record = this.#categories.get(normalizedCategory) ?? {
+      budget: 0,
+      expenses: [],
+    };
+
+    record.expenses.push(normalizeAmount(amount, "expense"));
+    this.#categories.set(normalizedCategory, record);
+    return this;
+  }
+
+  loadExpensesByCategory(expensesByCategory) {
+    if (Array.isArray(expensesByCategory)) {
+      for (const entry of expensesByCategory) {
+        if (!entry || typeof entry !== "object") {
+          throw new TypeError("expense entry must be an object");
+        }
+
+        const category = normalizeCategory(entry.category);
+        const values = "expenses" in entry ? normalizeExpenseList(entry.expenses) : normalizeExpenseList(entry.amount);
+
+        for (const value of values) {
+          this.addExpense(category, value);
+        }
+      }
+
+      return this;
+    }
+
+    if (!expensesByCategory || typeof expensesByCategory !== "object") {
+      throw new TypeError("expensesByCategory must be an object or an array");
+    }
+
+    for (const [category, value] of Object.entries(expensesByCategory)) {
+      const normalizedCategory = normalizeCategory(category);
+      const values = normalizeExpenseList(value);
+
+      for (const amount of values) {
+        this.addExpense(normalizedCategory, amount);
+      }
+    }
+
+    return this;
+  }
+
+  loadCategories(categories) {
+    if (Array.isArray(categories)) {
+      for (const entry of categories) {
+        if (!entry || typeof entry !== "object") {
+          throw new TypeError("category entry must be an object");
+        }
+
+        if (!("category" in entry)) {
+          throw new TypeError("category entry must include category");
+        }
+
+        const normalized = normalizeCategoryEntry(entry.category, entry);
+        this.#categories.set(normalized.category, {
+          budget: normalized.budget,
+          expenses: [...normalized.expenses],
+        });
+      }
+
+      return this;
+    }
+
+    if (!categories || typeof categories !== "object") {
+      throw new TypeError("categories must be an object or an array");
+    }
+
+    for (const [category, value] of Object.entries(categories)) {
+      const normalized = normalizeCategoryEntry(category, value);
+      this.#categories.set(normalized.category, {
+        budget: normalized.budget,
+        expenses: [...normalized.expenses],
+      });
+    }
+
+    return this;
+  }
+
+  getTotal() {
+    return this.#total;
+  }
+
+  getCategory(category) {
+    const normalizedCategory = normalizeCategory(category);
+    const record = this.#categories.get(normalizedCategory) ?? {
+      budget: 0,
+      expenses: [],
+    };
+
+    return summarizeCategory(normalizedCategory, record);
+  }
+
+  listCategories() {
+    return [...this.#categories.entries()].map(([category, record]) =>
+      summarizeCategory(category, record),
+    );
+  }
+
+  getSummary() {
+    const categories = this.listCategories();
+    const spent = categories.reduce((total, category) => total + category.spent, 0);
+
+    return {
+      total: this.#total,
+      spent,
+      available: this.#total - spent,
+      categories,
+    };
+  }
+
+  toJSON() {
+    return this.getSummary();
+  }
+}
+
+export function createBudget(initialValue = 0) {
+  return new Budget(initialValue);
+}
+
+export function definirPresupuestoTotal(total) {
+  return createBudget(total);
+}
+
+export function cargarGastosPorCategoria(expensesByCategory) {
+  return createBudget().loadExpensesByCategory(expensesByCategory);
+}
+
+export function calcularPresupuesto(budget) {
+  if (budget instanceof Budget) {
+    return budget.getSummary();
+  }
+
+  return createBudget(budget).getSummary();
+}
+
+export function calculateCategoryBudget(category, record) {
+  return summarizeCategory(normalizeCategory(category), {
+    budget: normalizeAmount(record.budget, "budget"),
+    expenses: normalizeExpenseList(record.expenses ?? []),
+  });
+}
+
