+      return this;
+    }
+
+    if (!expensesByCategory || typeof expensesByCategory !== "object") {
+      throw new TypeError("expensesByCategory must be an object or an array");
+    }
+
+    for (const [category, value] of Object.entries(expensesByCategory)) {
+      const normalizedCategory = normalizeCategory(category);
+      const values = normalizeExpenseList(value);
+
+      for (const amount of values) {
+        this.addExpense(normalizedCategory, amount);
+      }
+    }
+
+    return this;
+  }
+
+  loadCategories(categories) {
+    if (Array.isArray(categories)) {
+      for (const entry of categories) {
+        if (!entry || typeof entry !== "object") {
+          throw new TypeError("category entry must be an object");
+        }
+
+        if (!("category" in entry)) {
+          throw new TypeError("category entry must include category");
+        }
+
+        const normalized = normalizeCategoryEntry(entry.category, entry);
+        this.#categories.set(normalized.category, {
+          budget: normalized.budget,
+          expenses: [...normalized.expenses],
+        });
+      }
+
+      return this;
+    }
+
+    if (!categories || typeof categories !== "object") {
+      throw new TypeError("categories must be an object or an array");
+    }
+
+    for (const [category, value] of Object.entries(categories)) {
+      const normalized = normalizeCategoryEntry(category, value);
+      this.#categories.set(normalized.category, {
+        budget: normalized.budget,
+        expenses: [...normalized.expenses],
+      });
+    }
+
+    return this;
+  }
