+    return summarizeCategory(normalizedCategory, record);
+  }
+
+  listCategories() {
+    return [...this.#categories.entries()].map(([category, record]) =>
+      summarizeCategory(category, record),
+    );
+  }
+
+  getSummary() {
+    const categories = this.listCategories();
+    const spent = categories.reduce((total, category) => total + category.spent, 0);
+
+    return {
+      total: this.#total,
+      spent,
+      available: this.#total - spent,
+      categories,
+    };
+  }
+
+  toJSON() {
+    return this.getSummary();
+  }
+}
+
+export function createBudget(initialValue = 0) {
+  return new Budget(initialValue);
+}
+
+export function definirPresupuestoTotal(total) {
+  return createBudget(total);
+}
+
+export function cargarGastosPorCategoria(expensesByCategory) {
+  return createBudget().loadExpensesByCategory(expensesByCategory);
+}
+
+export function calcularPresupuesto(budget) {
+  if (budget instanceof Budget) {
