@@ -0,0 +1,53 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+import {
+  FavoritesStore,
+  clearFavorites,
+  hasFavorite,
+  listFavorites,
+  markFavorite,
+  unmarkFavorite
+} from "./favorites.mjs";
+
+test("favorites can be marked, unmarked, and listed together", () => {
+  clearFavorites();
+
+  const park = { id: "parque-central", kind: "place", name: "Parque Central" };
+  const museum = { id: "museo-ciudad", kind: "activity", name: "Museo de la Ciudad" };
+
+  assert.deepEqual(listFavorites(), []);
+
+  markFavorite(park);
+  markFavorite(museum);
+
+  assert.deepEqual(listFavorites(), [park, museum]);
+  assert.equal(hasFavorite(park), true);
+  assert.equal(hasFavorite(museum), true);
+
+  markFavorite({ ...park });
+  assert.deepEqual(listFavorites(), [park, museum]);
+
+  unmarkFavorite(park);
+
+  assert.deepEqual(listFavorites(), [museum]);
+  assert.equal(hasFavorite(park), false);
+  assert.equal(hasFavorite(museum), true);
+
+  clearFavorites();
+  assert.deepEqual(listFavorites(), []);
+});
+
+test("FavoritesStore keeps insertion order and returns defensive copies", () => {
+  const store = new FavoritesStore();
+  const favorite = { id: "cafe-largo", name: "Café Largo", tags: ["food"] };
+
+  store.mark(favorite);
+
+  const [listed] = store.list();
+  listed.name = "Changed";
+  listed.tags.push("updated");
+
+  assert.deepEqual(store.list(), [favorite]);
+  assert.equal(store.has({ id: "cafe-largo" }), true);
+});
+

