+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  addPackingItem,
+  completePackingItem,
+  createPackingChecklist,
+  filterPackingItems,
+  getPackingProgress,
+  packingFilters,
+  setPackingFilter,
+  togglePackingItem,
+} from "./packing.mjs";
+
+test("the packing checklist adds items and keeps them immutable", () => {
+  const checklist = createPackingChecklist();
+  const nextChecklist = addPackingItem(checklist, { id: "shirt", label: "Remera" });
+
+  assert.equal(checklist.items.length, 0);
+  assert.equal(nextChecklist.items.length, 1);
+  assert.deepEqual(nextChecklist.items[0], {
+    id: "shirt",
+    label: "Remera",
+    packed: false,
+  });
+});
+
+test("the packing checklist marks items as packed and can toggle them back", () => {
+  const checklist = createPackingChecklist([{ id: "toothbrush", label: "Cepillo", packed: false }]);
+  const completed = completePackingItem(checklist, "toothbrush");
+  const toggled = togglePackingItem(completed, "toothbrush");
+
+  assert.equal(completed.items[0].packed, true);
+  assert.equal(toggled.items[0].packed, false);
+});
+
+test("the packing checklist filters by completion state", () => {
+  const checklist = createPackingChecklist([
+    { id: "shirt", label: "Remera", packed: false },
+    { id: "socks", label: "Medias", packed: true },
+  ]);
+
+  const completedOnly = filterPackingItems(checklist, packingFilters.completed);
+  const pendingOnly = filterPackingItems(setPackingFilter(checklist, packingFilters.pending));
+
+  assert.deepEqual(
+    completedOnly.map((item) => item.id),
+    ["socks"],
+  );
+  assert.deepEqual(
+    pendingOnly.map((item) => item.id),
+    ["shirt"],
+  );
+});
+
+test("the packing checklist calculates total progress", () => {
+  const checklist = createPackingChecklist([
+    { id: "shirt", label: "Remera", packed: true },
+    { id: "socks", label: "Medias", packed: false },
+    { id: "book", label: "Libro", packed: true },
+  ]);
+
+  assert.deepEqual(getPackingProgress(checklist), {
+    completed: 2,
+    remaining: 1,
+    total: 3,
+    percentage: 67,
+  });
+});

