+import assert from "node:assert/strict";
+import test from "node:test";
+import exploreRoute, {
+  createRouteExplorer,
+  filterRouteExploration,
+  searchRouteExploration
+} from "./explore.mjs";
+
+const itinerary = [
+  { id: "a", title: "Museo de Arte", kind: "actividad", category: "cultura" },
+  { id: "b", title: "Almuerzo en el centro", kind: "parada", category: "comida" },
+  { id: "c", title: "Mirador del río", kind: "actividad", category: "paisaje" },
+  { id: "d", title: "Café y descanso", kind: "parada", category: "comida" }
+];
+
+test("exploreRoute filters and searches without changing itinerary order", () => {
+  const result = exploreRoute(itinerary, {
+    query: "a",
+    filters: { category: "comida" }
+  });
+
+  assert.deepEqual(result.map(({ id }) => id), ["b", "d"]);
+});
+
+test("filterRouteExploration keeps the original order when filtering", () => {
+  const result = filterRouteExploration(itinerary, { kind: "actividad" });
+
+  assert.deepEqual(result.map(({ id }) => id), ["a", "c"]);
+});
+
+test("searchRouteExploration keeps the original order when searching", () => {
+  const result = searchRouteExploration(itinerary, "o");
+
+  assert.deepEqual(result.map(({ id }) => id), ["a", "b", "c", "d"]);
+});
+
+test("createRouteExplorer reuses the same ordering rules", () => {
+  const explorer = createRouteExplorer({ fields: ["title"] });
+  const result = explorer.explore(itinerary, { query: "café" });
+
+  assert.deepEqual(result.map(({ id }) => id), ["d"]);
+});

