+const state = {
+  nextId: 1,
+  notes: []
+};
+
+function normalizeNoteInput(input) {
+  if (typeof input === "string") {
+    return { text: input };
+  }
+
+  if (input && typeof input === "object") {
+    return input;
+  }
+
+  return {};
+}
+
+function readText(input) {
+  const text = input.text ?? input.content ?? input.body;
+  if (typeof text !== "string" || text.trim() === "") {
+    throw new TypeError("A note needs non-empty text.");
+  }
+  return text;
+}
+
+function readAssociation(input) {
+  const dayId = input.dayId ?? null;
+  const stopId = input.stopId ?? null;
+  if (dayId == null && stopId == null) {
+    throw new TypeError("A note must be associated with a day or a stop.");
+  }
+  return { dayId, stopId };
+}
+
+function cloneNote(note) {
+  return { ...note };
+}
+
+export function createNote(input) {
+  const data = normalizeNoteInput(input);
+  const text = readText(data);
+  const association = readAssociation(data);
+  const note = {
+    id: `note-${state.nextId++}`,
+    text,
+    ...association
+  };
+
+  state.notes.push(note);
+  return cloneNote(note);
+}
+
+export function listNotes(filters = {}) {
+  const { dayId, stopId } = filters ?? {};
+
+  return state.notes
+    .filter((note) => (dayId === undefined || note.dayId === dayId) && (stopId === undefined || note.stopId === stopId))
+    .map(cloneNote);
+}
+
+export function resetNotes() {
+  state.nextId = 1;
+  state.notes = [];
+}
+
+export const addNote = createNote;
+export const getNotes = listNotes;
+
+export default {
+  addNote,
+  createNote,
+  getNotes,
+  listNotes,
+  resetNotes
+};
