+test("createNote stores a note associated with a day", () => {
+  const note = createNote({ text: "Pick up snacks", dayId: "day-1" });
+
+  assert.deepEqual(note, {
+    id: "note-1",
+    text: "Pick up snacks",
+    dayId: "day-1",
+    stopId: null
+  });
