+const ESTADOS_VALIDOS = new Set(["pendiente", "completada"]);
+
+function clonarActividad(actividad) {
+  return {
+    dia: actividad.dia,
+    parada: actividad.parada,
+    horario: actividad.horario,
+    estado: actividad.estado
+  };
+}
+
+function normalizarTexto(nombreCampo, valor) {
+  if (typeof valor !== "string" || valor.trim() === "") {
+    throw new TypeError(`${nombreCampo} debe ser una cadena no vacia`);
+  }
+  return valor.trim();
+}
+
+function normalizarEstado(estado) {
+  const valor = estado ?? "pendiente";
+  if (typeof valor !== "string" || !ESTADOS_VALIDOS.has(valor)) {
+    throw new RangeError("estado debe ser 'pendiente' o 'completada'");
+  }
+  return valor;
+}
+
+function normalizarActividad(actividad) {
+  if (!actividad || typeof actividad !== "object") {
+    throw new TypeError("actividad debe ser un objeto");
+  }
+
+  return {
+    dia: normalizarTexto("dia", actividad.dia),
+    parada: normalizarTexto("parada", actividad.parada),
+    horario: normalizarTexto("horario", actividad.horario),
+    estado: normalizarEstado(actividad.estado)
+  };
+}
+
+function resolverIndice(items, referencia) {
+  if (Number.isInteger(referencia)) {
+    return referencia >= 0 && referencia < items.length ? referencia : -1;
+  }
+
+  if (referencia && typeof referencia === "object") {
+    const indicePorReferencia = items.indexOf(referencia);
+    if (indicePorReferencia !== -1) {
+      return indicePorReferencia;
+    }
+
+    return items.findIndex((actividad) => (
+      actividad.dia === referencia.dia &&
+      actividad.parada === referencia.parada &&
+      actividad.horario === referencia.horario &&
+      actividad.estado === referencia.estado
+    ));
+  }
+
+  return -1;
+}
+
+export function crearAgendaDiaria(actividadesIniciales = []) {
+  const actividades = actividadesIniciales.map(normalizarActividad);
+
+  function agregarActividad(actividad) {
+    const normalizada = normalizarActividad(actividad);
+    actividades.push(normalizada);
+    return normalizada;
+  }
+
+  function listarActividades() {
+    return actividades.map(clonarActividad);
+  }
+
+  function obtenerActividad(referencia) {
+    const indice = resolverIndice(actividades, referencia);
+    return indice === -1 ? null : actividades[indice];
+  }
+
+  function actualizarEstadoActividad(referencia, estado) {
+    const indice = resolverIndice(actividades, referencia);
+    if (indice === -1) {
+      return null;
+    }
+
+    actividades[indice].estado = normalizarEstado(estado);
+    return actividades[indice];
+  }
+
+  function listarActividadesPorDia(dia) {
+    const valorDia = normalizarTexto("dia", dia);
+    return actividades.filter((actividad) => actividad.dia === valorDia).map(clonarActividad);
+  }
+
+  function listarActividadesPorParada(parada) {
+    const valorParada = normalizarTexto("parada", parada);
+    return actividades.filter((actividad) => actividad.parada === valorParada).map(clonarActividad);
+  }
+
+  return {
+    agregarActividad,
+    listarActividades,
+    obtenerActividad,
+    actualizarEstadoActividad,
+    marcarActividadComoCompletada(referencia) {
+      return actualizarEstadoActividad(referencia, "completada");
+    },
+    marcarActividadComoPendiente(referencia) {
+      return actualizarEstadoActividad(referencia, "pendiente");
+    },
+    listarActividadesPorDia,
+    listarActividadesPorParada
+  };
+}
+
+export const agendaDiaria = crearAgendaDiaria;
+export const crearAgenda = crearAgendaDiaria;
+
+export function agregarActividad(agenda, actividad) {
+  return agenda.agregarActividad(actividad);
+}
+
+export function marcarActividadComoCompletada(agenda, referencia) {
+  return agenda.marcarActividadComoCompletada(referencia);
+}
+
+export function marcarActividadComoPendiente(agenda, referencia) {
+  return agenda.marcarActividadComoPendiente(referencia);
+}
+
+export function listarActividadesPorDia(agenda, dia) {
+  return agenda.listarActividadesPorDia(dia);
+}
+
+export function listarActividadesPorParada(agenda, parada) {
+  return agenda.listarActividadesPorParada(parada);
+}
+
+export default {
+  crearAgendaDiaria,
+  agendaDiaria,
+  crearAgenda,
+  agregarActividad,
+  marcarActividadComoCompletada,
+  marcarActividadComoPendiente,
+  listarActividadesPorDia,
+  listarActividadesPorParada
+};
