@@ -0,0 +1,112 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  Budget,
+  calcularPresupuesto,
+  cargarGastosPorCategoria,
+  createBudget,
+  definirPresupuestoTotal,
+} from "./budget.mjs";
+
+// Definir presupuesto total, cargar gastos por categoría y mostrar gastado y disponible.
+// El presupuesto calcula gastado y disponible por categoría.
+test("the budget calculates spent and available per category", () => {
+  const budget = createBudget({ total: 1000 });
+
+  budget
+    .setCategoryBudget("food", 300)
+    .setCategoryBudget("transport", 200)
+    .addExpense("food", 120)
+    .addExpense("food", 30)
+    .addExpense("transport", 50);
+
+  assert.deepEqual(budget.getCategory("food"), {
+    category: "food",
+    budget: 300,
+    spent: 150,
+    available: 150,
+  });
+
+  assert.deepEqual(budget.getCategory("transport"), {
+    category: "transport",
+    budget: 200,
+    spent: 50,
+    available: 150,
+  });
+
+  assert.deepEqual(budget.getSummary(), {
+    total: 1000,
+    spent: 200,
+    available: 800,
+    categories: [
+      {
+        category: "food",
+        budget: 300,
+        spent: 150,
+        available: 150,
+      },
+      {
+        category: "transport",
+        budget: 200,
+        spent: 50,
+        available: 150,
+      },
+    ],
+  });
+});
+
+test("loadExpensesByCategory accepts grouped expenses and category definitions", () => {
+  const budget = new Budget({
+    total: 500,
+    categories: {
+      home: { budget: 250, expenses: [40] },
+      leisure: { budget: 100 },
+    },
+  });
+
+  budget.loadExpensesByCategory({
+    home: [10, 15],
+    leisure: 25,
+  });
+
+  assert.deepEqual(budget.listCategories(), [
+    {
+      category: "home",
+      budget: 250,
+      spent: 65,
+      available: 185,
+    },
+    {
+      category: "leisure",
+      budget: 100,
+      spent: 25,
+      available: 75,
+    },
+  ]);
+
+  assert.equal(calcularPresupuesto(budget).available, 410);
+});
+
+test("the Spanish helpers create and summarize a budget", () => {
+  const budget = definirPresupuestoTotal(250);
+  budget.setCategoryBudget("school", 120).addExpense("school", 20);
+
+  const summary = calcularPresupuesto(budget);
+  assert.equal(summary.total, 250);
+  assert.equal(summary.spent, 20);
+  assert.equal(summary.available, 230);
+  assert.equal(summary.categories[0].spent, 20);
+
+  const fromHelper = cargarGastosPorCategoria({
+    school: [10, 5],
+  }).setCategoryBudget("school", 50);
+
+  assert.ok(fromHelper instanceof Budget);
+  assert.deepEqual(fromHelper.getCategory("school"), {
+    category: "school",
+    budget: 50,
+    spent: 15,
+    available: 35,
+  });
+});

