+
+// Definir presupuesto total, cargar gastos por categoría y mostrar gastado y disponible.
+// El presupuesto calcula gastado y disponible por categoría.
+test("the budget calculates spent and available per category", () => {
+  const budget = createBudget({ total: 1000 });
+
+  budget
+    .setCategoryBudget("food", 300)
+    .setCategoryBudget("transport", 200)
+    .addExpense("food", 120)
+    .addExpense("food", 30)
+    .addExpense("transport", 50);
+
+  assert.deepEqual(budget.getCategory("food"), {
+    category: "food",
+    budget: 300,
+    spent: 150,
+    available: 150,
+  });
+
+  assert.deepEqual(budget.getCategory("transport"), {
+    category: "transport",
+    budget: 200,
+    spent: 50,
+    available: 150,
+  });
+
+  assert.deepEqual(budget.getSummary(), {
+    total: 1000,
+    spent: 200,
+    available: 800,
+    categories: [
+      {
+        category: "food",
+        budget: 300,
+        spent: 150,
+        available: 150,
+      },
+      {
+        category: "transport",
+        budget: 200,
+        spent: 50,
+        available: 150,
+      },
+    ],
+  });
+});
+
+test("loadExpensesByCategory accepts grouped expenses and category definitions", () => {
+  const budget = new Budget({
+    total: 500,
+    categories: {
+      home: { budget: 250, expenses: [40] },
+      leisure: { budget: 100 },
+    },
+  });
+
+  budget.loadExpensesByCategory({
+    home: [10, 15],
+    leisure: 25,
