+import { Budget, createBudget } from "../budget/budget.mjs";
+import {
+  addPackingItem as addPackingItemToChecklist,
+  createPackingChecklist,
+  getPackingProgress as readPackingProgress,
+  togglePackingItem as togglePackingChecklistItem,
+} from "../packing/packing.mjs";
+
+function isRecord(value) {
+  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
+}
+
+function normalizeCategory(category) {
+  if (typeof category !== "string") {
+    throw new TypeError("category must be a non-empty string");
+  }
+
+  const normalized = category.trim();
+  if (!normalized) {
+    throw new TypeError("category must be a non-empty string");
+  }
+
+  return normalized;
+}
+
+function normalizeAmount(amount, label = "amount") {
+  if (typeof amount !== "number" || !Number.isFinite(amount)) {
+    throw new TypeError(`${label} must be a finite number`);
+  }
+
+  return amount;
+}
+
+function normalizePackingItem(item) {
+  if (typeof item === "string") {
+    const label = item.trim();
+    if (!label) {
+      throw new TypeError("Packing item label must be a non-empty string");
+    }
+
+    return { label };
+  }
+
+  if (!isRecord(item)) {
+    throw new TypeError("Packing item must be an object or string");
+  }
+
+  if (typeof item.label === "string") {
+    const label = item.label.trim();
+    if (!label) {
+      throw new TypeError("Packing item label must be a non-empty string");
+    }
+
+    return {
+      ...item,
+      label,
+    };
+  }
+
+  throw new TypeError("Packing item label must be a non-empty string");
+}
+
+function cloneCategoriesMap(categories) {
+  const nextCategories = new Map();
+
+  if (categories instanceof Map) {
+    for (const [category, value] of categories.entries()) {
+      nextCategories.set(normalizeCategory(category), normalizeAmount(value, "budget"));
+    }
+
+    return nextCategories;
+  }
+
+  if (Array.isArray(categories)) {
+    for (const entry of categories) {
+      if (!isRecord(entry) || !("category" in entry)) {
+        throw new TypeError("category entry must be an object with category");
+      }
+
+      nextCategories.set(normalizeCategory(entry.category), normalizeAmount(entry.budget ?? 0, "budget"));
+    }
+
+    return nextCategories;
+  }
+
+  if (!isRecord(categories)) {
+    throw new TypeError("categories must be an object or an array");
+  }
+
+  for (const [category, value] of Object.entries(categories)) {
+    if (isRecord(value) && "budget" in value) {
+      nextCategories.set(normalizeCategory(category), normalizeAmount(value.budget, "budget"));
+      continue;
+    }
+
+    nextCategories.set(normalizeCategory(category), normalizeAmount(value, "budget"));
+  }
+
+  return nextCategories;
+}
+
+function cloneExpenseLedger(expensesByCategory) {
+  const nextExpenses = new Map();
+
+  if (expensesByCategory instanceof Map) {
+    for (const [category, values] of expensesByCategory.entries()) {
+      const normalizedCategory = normalizeCategory(category);
+      const list = Array.isArray(values) ? values : [values];
+      nextExpenses.set(
+        normalizedCategory,
+        list.map((value) => normalizeAmount(value, "expense")),
+      );
+    }
+
+    return nextExpenses;
+  }
+
+  if (!isRecord(expensesByCategory)) {
+    throw new TypeError("expensesByCategory must be an object or an array");
+  }
