+      if (!isRecord(entry) || !("category" in entry)) {
+        throw new TypeError("category entry must be an object with category");
+      }
+
+      nextCategories.set(normalizeCategory(entry.category), normalizeAmount(entry.budget ?? 0, "budget"));
+    }
+
