+  } else if ("total" in initialState || "categories" in initialState || "expensesByCategory" in initialState) {
+    loadBudgetState(state, initialState);
+  } else if (typeof initialState === "number") {
+    loadBudgetState(state, initialState);
+  }
+
+  if ("packing" in initialState) {
+    state.packingChecklist = createPackingChecklist(
