+    this.#state.expenseLedger.set(normalizedCategory, [...current, normalizedAmount]);
+    return this;
+  }
+
+  removeExpense(category, amount) {
+    const normalizedCategory = normalizeCategory(category);
+    removeExpenseFromLedger(this.#state.expenseLedger, normalizedCategory, amount);
+    return this;
+  }
+
+  getBudgetSummary() {
+    return createSummaryBudget(this.#state);
+  }
+
+  addPackingItem(item) {
+    const normalizedItem = normalizePackingItem(item);
+    this.#state.packingChecklist = addPackingItemToChecklist(this.#state.packingChecklist, normalizedItem);
+    return this;
+  }
+
+  togglePackingItem(id) {
+    this.#state.packingChecklist = togglePackingChecklistItem(this.#state.packingChecklist, id);
+    return this;
+  }
+
+  removePackingItem(id) {
+    this.#state.packingChecklist = removePackingItemById(this.#state.packingChecklist, id);
+    return this;
+  }
+
+  getPackingProgress() {
+    return readPackingProgress(this.#state.packingChecklist);
+  }
+
+  get state() {
+    return {
+      budgetTotal: this.#state.budgetTotal,
+      categories: [...this.#state.categoryBudgets.entries()].map(([category, budget]) => ({
+        category,
+        budget,
