+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  addExpense,
+  addPackingItem,
+  createOrganizationIntegration,
+  getBudgetSummary,
+  getPackingProgress,
+  removeExpense,
+  removePackingItem,
+  setBudget,
+  togglePackingItem,
+} from "./index.mjs";
+
+test("the organization integration exposes budget and packing as one cohesive module", () => {
+  const organization = createOrganizationIntegration({
+    budget: {
+      total: 1500,
+      categories: {
+        food: { budget: 500 },
+        transport: { budget: 250 },
+      },
+    },
+  });
+
+  organization
+    .addExpense("food", 120)
+    .addExpense("food", 80)
+    .addExpense("transport", 50)
+    .removeExpense("food", 120)
+    .addPackingItem({ id: "passport", label: "Pasaporte" })
+    .addPackingItem({ id: "charger", label: "Cargador", packed: true })
+    .togglePackingItem("passport")
+    .removePackingItem("charger");
+
+  assert.deepEqual(organization.getBudgetSummary(), {
+    total: 1500,
+    spent: 130,
+    available: 1370,
+    categories: [
+      {
+        category: "food",
+        budget: 500,
+        spent: 80,
+        available: 420,
+      },
+      {
+        category: "transport",
+        budget: 250,
+        spent: 50,
+        available: 200,
+      },
+    ],
+  });
+
+  assert.deepEqual(organization.getPackingProgress(), {
+    completed: 1,
+    remaining: 0,
+    total: 1,
+    percentage: 100,
+  });
+});
+
+test("the named integration operations can target a fresh instance", () => {
+  const organization = createOrganizationIntegration();
+
+  setBudget(organization, 900);
+  addExpense(organization, "food", 60);
+  addExpense(organization, "lodging", 120);
+  removeExpense(organization, "food", 60);
+  addPackingItem(organization, { id: "shoes", label: "Zapatos" });
+  togglePackingItem(organization, "shoes");
+  removePackingItem(organization, "shoes");
+
+  assert.deepEqual(getBudgetSummary(organization), {
+    total: 900,
+    spent: 120,
+    available: 780,
+    categories: [
+      {
+        category: "lodging",
+        budget: 0,
+        spent: 120,
+        available: -120,
+      },
+    ],
+  });
+
+  assert.deepEqual(getPackingProgress(organization), {
+    completed: 0,
+    remaining: 0,
+    total: 0,
+    percentage: 0,
+  });
+});

