import { randomUUID } from "node:crypto";

function text(value) {
  return String(value ?? "").trim();
}

function datesList(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => text(entry)).filter(Boolean);
  }

  const normalized = text(value);
  return normalized ? [normalized] : [];
}

function normalizeStop(stop = {}) {
  return {
    id: stop.id ?? randomUUID(),
    name: text(stop.name),
    dates: datesList(stop.dates),
    description: text(stop.description)
  };
}

function applyStopPatch(stop, patch = {}) {
  return {
    id: stop.id,
    name: Object.hasOwn(patch, "name") ? text(patch.name) : stop.name,
    dates: Object.hasOwn(patch, "dates") ? datesList(patch.dates) : stop.dates,
    description: Object.hasOwn(patch, "description") ? text(patch.description) : stop.description
  };
}

export function createStops(initialStops = []) {
  return initialStops.map((stop) => normalizeStop(stop));
}

export function addStop(stops, stop) {
  return [...stops, normalizeStop(stop)];
}

export function editStop(stops, id, patch) {
  return stops.map((stop) => (stop.id === id ? applyStopPatch(stop, patch) : stop));
}

export function deleteStop(stops, id) {
  return stops.filter((stop) => stop.id !== id);
}

export function reorderStop(stops, fromIndex, toIndex) {
  const sourceIndex = Number.isInteger(fromIndex) ? fromIndex : Number(fromIndex);
  const targetIndex = Number.isInteger(toIndex) ? toIndex : Number(toIndex);

  if (!Number.isInteger(sourceIndex) || !Number.isInteger(targetIndex)) {
    return stops;
  }

  if (sourceIndex < 0 || sourceIndex >= stops.length) {
    return stops;
  }

  const destinationIndex = Math.max(0, Math.min(targetIndex, stops.length));

  if (sourceIndex === destinationIndex) {
    return stops;
  }

  const reordered = [...stops];
  const [moved] = reordered.splice(sourceIndex, 1);
  reordered.splice(destinationIndex, 0, moved);
  return reordered;
}

