+import assert from "node:assert/strict";
+import test from "node:test";
+
+import integration, {
+  addActivity,
+  createStop,
+  removeActivity,
+  removeStop,
+  reorderStops,
+  searchItinerary,
+  toggleActivityStatus,
+  updateActivity,
+  updateStop
+} from "./index.mjs";
+
+test("el modulo de itinerario expone la superficie del contrato", () => {
+  assert.equal(typeof createStop, "function");
+  assert.equal(typeof updateStop, "function");
+  assert.equal(typeof removeStop, "function");
+  assert.equal(typeof reorderStops, "function");
+  assert.equal(typeof addActivity, "function");
+  assert.equal(typeof updateActivity, "function");
+  assert.equal(typeof toggleActivityStatus, "function");
+  assert.equal(typeof removeActivity, "function");
+  assert.equal(typeof searchItinerary, "function");
+
+  assert.equal(integration.createStop, createStop);
+  assert.equal(integration.searchItinerary, searchItinerary);
+});
+
+test("las paradas se normalizan y se pueden administrar como una coleccion", () => {
+  const stop = createStop({
+    name: "  Mendoza  ",
+    dates: ["2026-08-22", " "],
+    description: "  Noche intermedia "
+  });
+
+  assert.equal(stop.name, "Mendoza");
+  assert.deepEqual(stop.dates, ["2026-08-22"]);
+  assert.equal(stop.description, "Noche intermedia");
+
+  const stops = [
+    { id: "a", name: "Buenos Aires", dates: ["2026-08-21"], description: "Inicio" },
+    { id: "b", name: "Rosario", dates: ["2026-08-22"], description: "Media ruta" },
+    { id: "c", name: "Mendoza", dates: ["2026-08-23"], description: "Destino" }
+  ];
+
+  assert.deepEqual(updateStop(stops, "b", { name: "Rosario centro" }), [
+    { id: "a", name: "Buenos Aires", dates: ["2026-08-21"], description: "Inicio" },
+    { id: "b", name: "Rosario centro", dates: ["2026-08-22"], description: "Media ruta" },
+    { id: "c", name: "Mendoza", dates: ["2026-08-23"], description: "Destino" }
+  ]);
+
+  assert.deepEqual(removeStop(stops, "a"), [
+    { id: "b", name: "Rosario", dates: ["2026-08-22"], description: "Media ruta" },
+    { id: "c", name: "Mendoza", dates: ["2026-08-23"], description: "Destino" }
+  ]);
+
+  assert.deepEqual(reorderStops(stops, 0, 2).map(({ id }) => id), ["b", "c", "a"]);
+});
+
+test("las actividades se integran con actualizacion de estado y busqueda", () => {
+  const itinerary = {
+    stops: [
+      { id: "stop-a", name: "Buenos Aires", dates: ["2026-08-21"], description: "Inicio" }
+    ],
+    activities: []
+  };
+
+  const withFirstActivity = addActivity(itinerary, {
+    dia: "2026-08-21",
+    parada: "Buenos Aires",
+    horario: "09:30",
+    estado: "pendiente"
+  });
+
+  assert.equal(withFirstActivity.activities.length, 1);
+  assert.equal(withFirstActivity.activities[0].estado, "pendiente");
+
+  const updated = updateActivity(withFirstActivity, 0, {
+    horario: "10:00"
+  });
+
+  assert.equal(updated.activities[0].horario, "10:00");
+
+  const toggled = toggleActivityStatus(updated, 0);
+  assert.equal(toggled.activities[0].estado, "completada");
+
+  const removed = removeActivity(toggled, 0);
+  assert.deepEqual(removed.activities, []);
+
+  const results = searchItinerary(
+    {
+      stops: [
+        { id: "stop-a", name: "Buenos Aires", dates: ["2026-08-21"], description: "Inicio" },
+        { id: "stop-b", name: "Rosario", dates: ["2026-08-22"], description: "Escala" }
+      ],
+      activities: [
+        { dia: "2026-08-21", parada: "Buenos Aires", horario: "09:30", estado: "pendiente" },
+        { dia: "2026-08-22", parada: "Rosario", horario: "11:00", estado: "completada" }
+      ]
+    },
+    { query: "ros", filters: { } }
+  );
+
+  assert.deepEqual(results.map((item) => item.name ?? item.parada), ["Rosario", "Rosario"]);
+});

