function text(value) {
  return String(value ?? "").trim();
}

function datesList(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => text(entry)).filter(Boolean);
  }

  const normalized = text(value);
  return normalized ? [normalized] : [];
}

function normalizeStop(stop = {}) {
  return {
    id: stop.id ?? randomUUID(),
    name: text(stop.name),
    dates: datesList(stop.dates),
    description: text(stop.description)
  };
}

function applyStopPatch(stop, patch = {}) {
  return {
    id: stop.id,
    name: Object.hasOwn(patch, "name") ? text(patch.name) : stop.name,
    dates: Object.hasOwn(patch, "dates") ? datesList(patch.dates) : stop.dates,
    description: Object.hasOwn(patch, "description") ? text(patch.description) : stop.description
  };
}

export function createStops(initialStops = []) {
