+export function reorderStops(stops, fromIndex, toIndex) {
+  return reorderStop(stops, fromIndex, toIndex);
+}
+
+export function addActivity(agenda, activity) {
+  return agregarActividad(agenda, activity);
+}
+
+export function updateActivity(agenda, reference, patch = {}) {
+  const activity = agenda.obtenerActividad(reference);
+  if (!activity) {
+    return null;
+  }
+
+  if (Object.hasOwn(patch, "dia")) {
+    activity.dia = String(patch.dia ?? "").trim();
+  }
+
+  if (Object.hasOwn(patch, "parada")) {
+    activity.parada = String(patch.parada ?? "").trim();
+  }
+
+  if (Object.hasOwn(patch, "horario")) {
