+  listarActividadesPorDia,
+  listarActividadesPorParada,
+  marcarActividadComoCompletada,
+  marcarActividadComoPendiente
+} from "../agenda/agenda.mjs";
+import {
+  exploreRoute,
+  filterRouteExploration,
+  searchRouteExploration
+} from "../explore/explore.mjs";
+
+const ESTADOS_VALIDOS = new Set(["pendiente", "completada"]);
+
+function normalizarTexto(valor) {
+  const texto = String(valor ?? "").trim();
+  if (texto === "") {
+    throw new TypeError("el valor debe ser una cadena no vacia");
+  }
+
+  return texto;
+}
+
+function normalizarEstado(valor) {
+  if (typeof valor !== "string" || !ESTADOS_VALIDOS.has(valor)) {
+    throw new RangeError("estado debe ser 'pendiente' o 'completada'");
+  }
+
+  return valor;
+}
+
+export function createStop(stops, stop) {
+  return addStop(stops, stop);
+}
+
+export function updateStop(stops, id, patch) {
+  return editStop(stops, id, patch);
+}
+
+export function removeStop(stops, id) {
+  return deleteStop(stops, id);
+}
+
+export function reorderStops(stops, fromIndex, toIndex) {
+  return reorderStop(stops, fromIndex, toIndex);
+}
+
+export function addActivity(agenda, activity) {
+  return agregarActividad(agenda, activity);
+}
+
+export function updateActivity(agenda, reference, patch = {}) {
+  const activity = agenda.obtenerActividad(reference);
+  if (!activity) {
+    return null;
+  }
+
+  if (Object.hasOwn(patch, "dia")) {
+    activity.dia = normalizarTexto(patch.dia);
+  }
+
+  if (Object.hasOwn(patch, "parada")) {
+    activity.parada = normalizarTexto(patch.parada);
+  }
+
+  if (Object.hasOwn(patch, "horario")) {
+    activity.horario = normalizarTexto(patch.horario);
+  }
+
+  if (Object.hasOwn(patch, "estado")) {
+    activity.estado = normalizarEstado(patch.estado);
+  }
+
+  return activity;
+}
+
+export function toggleActivityStatus(agenda, reference) {
+  const activity = agenda.obtenerActividad(reference);
+  if (!activity) {
+    return null;
+  }
+
+  return activity.estado === "completada"
+    ? marcarActividadComoPendiente(agenda, activity)
+    : marcarActividadComoCompletada(agenda, activity);
+}
+
+export function removeActivity(agenda, reference) {
+  const activities = agenda.listarActividades();
+  const target = agenda.obtenerActividad(reference);
+
+  if (!target) {
+    return null;
+  }
+
+  const remaining = activities.filter((activity) => !(
+    activity.dia === target.dia &&
+    activity.parada === target.parada &&
+    activity.horario === target.horario &&
+    activity.estado === target.estado
+  ));
+  return Object.assign(agenda, crearAgendaDiaria(remaining));
+}
+
+export function searchItinerary(items, query = "", filters = {}, fields) {
+  if (Array.isArray(fields)) {
+    return exploreRoute(items, { query, filters, fields });
+  }
+
+  if (typeof fields === "object" && fields !== null) {
+    return exploreRoute(items, { query, filters, ...fields });
+  }
+
+  return exploreRoute(items, { query, filters });
+}
+
+export {
+  createStops,
+  crearAgendaDiaria,
+  listarActividadesPorDia,
+  listarActividadesPorParada,
+  filterRouteExploration,
+  searchRouteExploration
+};
+
+export default {
+  createStop,
+  updateStop,
+  removeStop,
+  reorderStops,
+  addActivity,
+  updateActivity,
+  toggleActivityStatus,
+  removeActivity,
+  searchItinerary,
+  createStops,
+  crearAgendaDiaria,
+  listarActividadesPorDia,
+  listarActividadesPorParada,
+  filterRouteExploration,
+  searchRouteExploration
+};
