      { dia: "2026-08-22", parada: "Rosario", horario: "13:30", estado: "completada" },
    ],
    search: "",
  },
};

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function clone(value) {
  if (typeof structuredClone === "function") {
    return structuredClone(value);
  }

  return JSON.parse(JSON.stringify(value));
}

function normalizeText(value, fallback = "") {
  return typeof value === "string" ? value.trim() : fallback;
}

function normalizeList(value) {
  return Array.isArray(value) ? value : [];
}

function normalizeSnapshot(snapshot = DEFAULT_STATE) {
  const source = isRecord(snapshot) ? snapshot : DEFAULT_STATE;
  const organization = isRecord(source.organization) ? source.organization : DEFAULT_STATE.organization;
  const memories = isRecord(source.memories) ? source.memories : DEFAULT_STATE.memories;
  const route = isRecord(source.route) ? source.route : DEFAULT_STATE.route;

  return {
    organization: {
      budget: {
        total: isRecord(organization.budget) && Number.isFinite(organization.budget.total)
          ? organization.budget.total
          : DEFAULT_STATE.organization.budget.total,
        categories: isRecord(organization.budget) && isRecord(organization.budget.categories)
          ? clone(organization.budget.categories)
          : clone(DEFAULT_STATE.organization.budget.categories),
        expensesByCategory: isRecord(organization.budget) && isRecord(organization.budget.expensesByCategory)
          ? clone(organization.budget.expensesByCategory)
          : clone(DEFAULT_STATE.organization.budget.expensesByCategory),
      },
      packing: {
        items: normalizeList(organization.packing?.items).map((item) => ({
          id: normalizeText(item?.id),
          label: normalizeText(item?.label),
          packed: Boolean(item?.packed),
        })).filter((item) => item.id && item.label),
      },
    },
    memories: {
      notes: normalizeList(memories.notes).map((note) => ({
        id: normalizeText(note?.id),
        text: normalizeText(note?.text),
        dayId: normalizeText(note?.dayId),
        stopId: normalizeText(note?.stopId),
      })).filter((note) => note.id && note.text && (note.dayId || note.stopId)),
      favorites: normalizeList(memories.favorites).map((favorite) => ({
        id: normalizeText(favorite?.id),
        refId: normalizeText(favorite?.refId),
        refType: normalizeText(favorite?.refType),
        label: normalizeText(favorite?.label),
      })).filter((favorite) => favorite.id && favorite.refId && favorite.refType && favorite.label),
    },
    route: {
      stops: normalizeList(route.stops).map((stop) => ({
        id: normalizeText(stop?.id),
        name: normalizeText(stop?.name),
        dates: normalizeList(stop?.dates).map((date) => normalizeText(date)).filter(Boolean),
        description: normalizeText(stop?.description),
      })).filter((stop) => stop.id && stop.name),
      activities: normalizeList(route.activities).map((activity) => ({
        dia: normalizeText(activity?.dia),
        parada: normalizeText(activity?.parada),
        horario: normalizeText(activity?.horario),
        estado: normalizeText(activity?.estado, "pendiente"),
      })).filter((activity) => activity.dia && activity.parada && activity.horario),
      search: normalizeText(route.search),
    },
  };
}

function toBudgetInput(budgetState) {
  return {
    total: budgetState.total,
    categories: Object.fromEntries(
      Object.entries(budgetState.categories).map(([category, value]) => [
        category,
        { budget: Number.isFinite(value?.budget) ? value.budget : 0 },
      ]),
    ),
    expensesByCategory: Object.fromEntries(
      Object.entries(budgetState.expensesByCategory).map(([category, values]) => [
        category,
        normalizeList(values).map((value) => Number(value)).filter(Number.isFinite),
      ]),
    ),
  };
}

function cloneNotes(notes) {
  return notes.map((note) => ({ ...note }));
}

function cloneFavorites(favorites) {
  return favorites.map((favorite) => ({ ...favorite }));
}

function cloneStops(stops) {
  return stops.map((stop) => ({ ...stop, dates: [...stop.dates] }));
}

function cloneActivities(activities) {
  return activities.map((activity) => ({ ...activity }));
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function numberOrNull(value) {
  if (value === "" || value == null) {
    return null;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function readFormValue(formData, key) {
  const value = formData.get(key);
  return typeof value === "string" ? value.trim() : "";
}

function buildRouteSearchItems(stops, activities) {
  const stopItems = stops.map((stop) => ({
    kind: "stop",
    id: stop.id,
    name: stop.name,
    title: stop.name,
    description: stop.description,
    category: "stop",
  }));

  const activityItems = activities.map((activity, index) => ({
    kind: "activity",
    id: `activity-${index}`,
    name: activity.parada,
    title: `${activity.dia} ${activity.horario}`,
    description: activity.estado,
    category: activity.estado,
    dia: activity.dia,
    horario: activity.horario,
  }));

  return [...stopItems, ...activityItems];
}

function routeSearchFields() {
  return ["name", "title", "description", "kind", "category", "dia", "horario"];
}

function mapStopsToSelectOptions(stops) {
  return stops.map((stop) => `<option value="${escapeHtml(stop.id)}">${escapeHtml(stop.name)}</option>`).join("");
}

