function loadSnapshotFromStorage(storage) {
  if (!storage || typeof storage.getItem !== "function") {
    return null;
  }

  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) {
      return null;
    }

    return normalizeSnapshot(JSON.parse(raw));
  } catch {
    return null;
  }
}

function saveSnapshotToStorage(storage, snapshot) {
  if (!storage || typeof storage.setItem !== "function") {
    return;
  }

  storage.setItem(STORAGE_KEY, JSON.stringify(snapshot));
}

function cloneOrganizationSnapshot(organization) {
  return {
    budget: {
      total: organization.budgetTotal,
      categories: Object.fromEntries(
        organization.categories.map(({ category, budget }) => [category, { budget }]),
      ),
      expensesByCategory: Object.fromEntries(
        organization.expensesByCategory.map(({ category, expenses }) => [category, [...expenses]]),
      ),
    },
    packing: {
      items: organization.packing.items.map((item) => ({ ...item })),
    },
  };
}

function syncMemoriesFromSnapshot(memories) {
  resetMemories();

  for (const note of memories.notes) {
    addNote({
      id: note.id,
      text: note.text,
      dayId: note.dayId || undefined,
      stopId: note.stopId || undefined,
    });
  }

  for (const favorite of memories.favorites) {
    addFavorite({ ...favorite });
  }
}

function organizationFromSnapshot(snapshot) {
  return createOrganizationIntegration(snapshot);
}

function routeFromSnapshot(snapshot) {
  return {
    stops: createStop([], { id: "__bootstrap__", name: "", dates: [], description: "" }),
    agenda: crearAgendaDiaria([]),
  };
}

export class DashboardApp {
  #document;
  #storage;
  #target;
  #organization;
  #stops;
  #agenda;
  #routeQuery = "";
  #onSubmit;
  #onClick;
  #onInput;

  constructor({ document = globalThis.document, storage = globalThis.localStorage, initialState } = {}) {
    this.#document = document ?? null;
    this.#storage = storage ?? null;
    const snapshot = normalizeSnapshot(initialState ?? loadSnapshotFromStorage(this.#storage) ?? DEFAULT_STATE);

    this.#organization = organizationFromSnapshot(snapshot.organization);
    this.#stops = createStop([], { id: "__placeholder__", name: "", dates: [], description: "" }).filter(Boolean);
    this.#stops = createStop([], { id: "__placeholder__", name: "", dates: [], description: "" }).slice(0, 0);
    this.#stops = createStop([], { id: "__placeholder__", name: "", dates: [], description: "" });
    this.#stops = snapshot.route.stops.length > 0 ? cloneStops(snapshot.route.stops) : cloneStops(DEFAULT_STATE.route.stops);
    this.#agenda = crearAgendaDiaria(snapshot.route.activities.length > 0 ? cloneActivities(snapshot.route.activities) : cloneActivities(DEFAULT_STATE.route.activities));
    this.#routeQuery = snapshot.route.search;
    syncMemoriesFromSnapshot(snapshot.memories.notes.length > 0 || snapshot.memories.favorites.length > 0 ? snapshot.memories : DEFAULT_STATE.memories);

    this.#onSubmit = (event) => {
      const form = event.target instanceof HTMLElement ? event.target.closest("form[data-form]") : null;
      if (!form) {
        return;
      }

      event.preventDefault();
      this.#handleFormSubmit(form);
    };

    this.#onClick = (event) => {
      const button = event.target instanceof HTMLElement ? event.target.closest("[data-action]") : null;
      if (!button) {
        return;
      }

      event.preventDefault();
      this.#handleAction(button);
    };

    this.#onInput = (event) => {
      const input = event.target instanceof HTMLElement ? event.target.closest("[data-live='route-search']") : null;
      if (!input || !(input instanceof HTMLInputElement)) {
        return;
      }

      this.#routeQuery = input.value;
      this.persist();
      this.render();
    };
  }

  mount(target = this.#document?.getElementById("app") ?? this.#document?.body) {
    this.#target = target ?? null;

    if (this.#target && typeof this.#target.addEventListener === "function") {
      this.#target.addEventListener("submit", this.#onSubmit);
      this.#target.addEventListener("click", this.#onClick);
      this.#target.addEventListener("input", this.#onInput);
    }

    this.render();
    return this;
  }

  unmount() {
    if (this.#target && typeof this.#target.removeEventListener === "function") {
      this.#target.removeEventListener("submit", this.#onSubmit);
      this.#target.removeEventListener("click", this.#onClick);
      this.#target.removeEventListener("input", this.#onInput);
    }

    this.#target = null;
  }

  snapshot() {
    return {
      organization: cloneOrganizationSnapshot(this.#organization.state),
      memories: {
        notes: cloneNotes(listNotes()),
        favorites: cloneFavorites(listFavorites()),
      },
      route: {
        stops: cloneStops(this.#stops),
        activities: cloneActivities(this.#agenda.listarActividades()),
        search: this.#routeQuery,
      },
    };
  }

  persist() {
    saveSnapshotToStorage(this.#storage, this.snapshot());
  }

  render() {
    if (!this.#target) {
      return;
    }

    this.#target.innerHTML = renderDashboardHTML(this.view());
  }

  view() {
    const summary = getBudgetSummary(this.#organization);
    const packing = getPackingProgress(this.#organization);
    const notes = listNotes();
    const favorites = listFavorites();

    return {
      summary,
      packing,
      notes,
      favorites,
      stops: cloneStops(this.#stops),
      activities: cloneActivities(this.#agenda.listarActividades()),
      routeQuery: this.#routeQuery,
      routeHits: this.#routeQuery
        ? searchItinerary(buildRouteSearchItems(this.#stops, this.#agenda.listarActividades()), this.#routeQuery, {}, routeSearchFields())
        : [],
    };
  }

  #handleFormSubmit(form) {
    const data = new FormData(form);

    switch (form.dataset.form) {
      case "budget-total": {
        const total = numberOrNull(readFormValue(data, "total"));
        if (total != null) {
          setBudget(this.#organization, { ...toBudgetInput(cloneOrganizationSnapshot(this.#organization.state).budget), total });
        }
        break;
      }
      case "category-budget": {
        const category = readFormValue(data, "category");
        const budget = numberOrNull(readFormValue(data, "budget"));
        if (category && budget != null) {
          const current = cloneOrganizationSnapshot(this.#organization.state).budget;
          setBudget(this.#organization, {
            ...current,
            categories: {
              ...current.categories,
              [category]: { budget },
            },
          });
        }
        break;
      }
      case "expense": {
        const category = readFormValue(data, "category");
        const amount = numberOrNull(readFormValue(data, "amount"));
        if (category && amount != null) {
          addExpense(this.#organization, category, amount);
        }
        break;
      }
      case "packing-item": {
        const label = readFormValue(data, "label");
        if (label) {
          addPackingItem(this.#organization, {
            id: `packing-${Date.now()}`,
            label,
            packed: false,
          });
        }
        break;
      }
      case "stop": {
        const name = readFormValue(data, "name");
        if (name) {
          this.#stops = createStop(this.#stops, {
            name,
            dates: readFormValue(data, "dates"),
            description: readFormValue(data, "description"),
          });
        }
        break;
      }
      case "activity": {
        const dia = readFormValue(data, "dia");
        const parada = readFormValue(data, "parada");
        const horario = readFormValue(data, "horario");
        const estado = readFormValue(data, "estado") || "pendiente";
        if (dia && parada && horario) {
          this.#agenda = addActivity(this.#agenda, {
            dia,
            parada,
            horario,
            estado,
          });
        }
        break;
      }
      case "note": {
        const text = readFormValue(data, "text");
        const stopId = readFormValue(data, "stopId");
        if (text && stopId) {
          addNote({ text, stopId });
        }
        break;
      }
      case "favorite": {
        const refType = readFormValue(data, "refType");
        const refId = readFormValue(data, "refId");
        const label = readFormValue(data, "label");
        if (refType && refId && label) {
          addFavorite({
            id: refId,
            refId,
            refType,
            label,
          });
        }
        break;
      }
      case "route-search": {
        this.#routeQuery = readFormValue(data, "query");
        break;
      }
      default:
        break;
    }

    this.persist();
    this.render();
  }

  #handleAction(button) {
    const action = button.dataset.action;
    const id = button.dataset.id ?? "";
    const index = Number(button.dataset.index);

    switch (action) {
      case "toggle-packing":
        if (id) {
          togglePackingItem(this.#organization, id);
        }
        break;
      case "remove-packing":
        if (id) {
          removePackingItem(this.#organization, id);
        }
        break;
      case "remove-note":
        if (id) {
          removeNote(id);
        }
        break;
      case "remove-favorite":
        if (id) {
          removeFavorite({ id });
        }
        break;
      case "remove-stop":
        if (id) {
          this.#stops = removeStop(this.#stops, id);
        }
        break;
      case "move-stop-up":
        if (Number.isInteger(index)) {
          this.#stops = reorderStops(this.#stops, index, Math.max(0, index - 1));
        }
        break;
      case "move-stop-down":
        if (Number.isInteger(index)) {
          this.#stops = reorderStops(this.#stops, index, Math.min(this.#stops.length - 1, index + 1));
        }
        break;
      case "toggle-activity":
        if (Number.isInteger(index)) {
          this.#agenda = toggleActivityStatus(this.#agenda, index);
        }
        break;
      case "remove-activity":
        if (Number.isInteger(index)) {
          this.#agenda = removeActivity(this.#agenda, index);
        }
        break;
      default:
        break;
    }

    this.persist();
    this.render();
  }
}

export function createDashboardApp(options = {}) {
  return new DashboardApp(options);
}

export function loadDashboardSnapshot(storage = globalThis.localStorage) {
  return loadSnapshotFromStorage(storage);
}


