+                ${budgetSummary.categories.map((entry) => renderExpenseItem(entry)).join("")}
+              </ul>
+            </div>
+            <div class="stack">
+              <article class="progress-card" aria-label="Progreso del equipaje">
+                <div>
+                  <p class="eyebrow">Equipaje</p>
+                  <h3>${packingProgress.completed} de ${packingProgress.total}</h3>
+                </div>
+                <div class="progress-bar" aria-hidden="true">
+                  <span style="width: ${packingProgress.percentage}%"></span>
+                </div>
+                <p>${packingProgress.remaining} pendientes</p>
+              </article>
+              <form class="card-form" data-action="add-packing">
+                <h3>Agregar ítem</h3>
+                <label>
+                  <span>Nombre</span>
+                  <input name="label" type="text" placeholder="Botellas de agua" required />
+                </label>
+                <button type="submit">Guardar ítem</button>
+              </form>
+              <ul class="item-list">
+                ${runtime.organization.state.packing.items.map((item, index) => renderPackingItem(item, index)).join("")}
+              </ul>
+            </div>
+          </div>
+        </section>
+
+        <section class="panel panel--memories" aria-labelledby="memories-title">
+          <header class="panel__header">
+            <div>
+              <p class="eyebrow">Recuerdos</p>
+              <h2 id="memories-title">Notas y favoritos</h2>
+            </div>
+          </header>
+          <div class="panel__body">
+            <div class="split-list">
+              <form class="card-form" data-action="add-note">
+                <h3>Agregar nota</h3>
+                <label>
+                  <span>Texto</span>
+                  <textarea name="text" rows="3" placeholder="Reservar cena y confirmar horarios" required></textarea>
+                </label>
+                <label>
+                  <span>Parada asociada</span>
+                  <input name="stopId" type="text" placeholder="stop-costa" />
+                </label>
+                <button type="submit">Guardar nota</button>
+              </form>
+              <form class="card-form" data-action="add-favorite">
+                <h3>Agregar favorito</h3>
+                <label>
+                  <span>Tipo</span>
+                  <input name="refType" type="text" placeholder="stop" required />
+                </label>
+                <label>
+                  <span>Referencia</span>
+                  <input name="refId" type="text" placeholder="stop-costa" required />
+                </label>
+                <label>
+                  <span>Etiqueta</span>
+                  <input name="label" type="text" placeholder="Mirador favorito" required />
+                </label>
+                <button type="submit">Guardar favorito</button>
+              </form>
+            </div>
+            <div class="split-list">
+              <div>
+                <h3>Notas</h3>
+                <ul class="item-list">
+                  ${runtime.memories.notes.map((note) => renderNoteItem(note)).join("")}
+                </ul>
+              </div>
+              <div>
+                <h3>Favoritos</h3>
+                <ul class="item-list">
+                  ${runtime.memories.favorites.map((favorite) => renderFavoriteItem(favorite)).join("")}
+                </ul>
+              </div>
+            </div>
+          </div>
+        </section>
+      </main>
+    </div>
+  `;
+}
+
+function readField(formData, name) {
+  const value = formData.get(name);
+  return typeof value === "string" ? value.trim() : "";
+}
+
+function persistAndRender(app) {
+  app.runtime.updatedAt = isoDate();
+  app.runtime.memories.notes = listNotes();
+  app.runtime.memories.favorites = listFavorites();
+  saveDashboardSnapshot(serializeRuntime(app.runtime), app.storage);
+  app.root.innerHTML = renderDashboardHTML(app.runtime);
+}
+
+function updateRouteActivities(app, nextActivities) {
+  app.runtime.route.agenda = crearAgendaDiaria(nextActivities);
+}
+
+function syncMemoriesSnapshot(app) {
+  app.runtime.memories.notes = listNotes();
+  app.runtime.memories.favorites = listFavorites();
+}
+
+export function createDashboardApp({
+  root = globalThis.document?.querySelector?.("#app") ?? globalThis.document?.body ?? null,
+  storage = globalThis.localStorage,
+  snapshot = null,
+} = {}) {
+  const runtime = createRuntime(snapshot ?? loadDashboardSnapshot(storage));
+  const app = { root, storage, runtime };
+
+  function render() {
+    if (!app.root) {
+      return;
+    }
+
+    app.root.innerHTML = renderDashboardHTML(app.runtime);
+  }
+
+  function handleSubmit(event) {
+    const form = event.target;
+    if (!(form instanceof HTMLFormElement)) {
+      return;
+    }
+
+    const action = form.dataset.action;
+    if (!action) {
+      return;
+    }
+
+    const data = new FormData(form);
+
+    switch (action) {
+      case "search-itinerary":
+        app.runtime.routeQuery = readField(data, "query");
+        break;
+      case "add-stop": {
+        const name = readField(data, "name");
+        if (name) {
+          app.runtime.route.stops = createStop(app.runtime.route.stops, {
+            name,
+            dates: readField(data, "dates"),
+            description: readField(data, "description"),
+          });
+        }
+        break;
+      }
+      case "add-activity": {
+        const dia = readField(data, "dia");
+        const parada = readField(data, "parada");
+        const horario = readField(data, "horario");
+        const estado = readField(data, "estado") || "pendiente";
+        if (dia && parada && horario) {
+          addActivity(app.runtime.route.agenda, { dia, parada, horario, estado });
+        }
+        break;
+      }
+      case "set-budget": {
+        const total = readField(data, "total");
+        if (total) {
+          app.runtime.organization.setBudget(Number(total));
+        }
+        break;
+      }
+      case "add-expense": {
+        const category = readField(data, "category");
+        const amount = readField(data, "amount");
+        if (category && amount) {
+          app.runtime.organization.addExpense(category, Number(amount));
+        }
+        break;
+      }
+      case "add-packing": {
+        const label = readField(data, "label");
+        if (label) {
+          app.runtime.organization.addPackingItem({ label });
+        }
+        break;
+      }
+      case "add-note": {
+        const text = readField(data, "text");
+        const stopId = readField(data, "stopId");
+        if (text) {
+          addNote(stopId ? { text, stopId } : { text, stopId: "stop-salida" });
+          syncMemoriesSnapshot(app);
+        }
+        break;
+      }
+      case "add-favorite": {
+        const refType = readField(data, "refType");
+        const refId = readField(data, "refId");
+        const label = readField(data, "label");
+        if (refType && refId && label) {
+          addFavorite({ id: refId, refType, refId, label });
+          syncMemoriesSnapshot(app);
+        }
+        break;
+      }
+      default:
+        break;
+    }
+
+    persistAndRender(app);
+  }
+
+  function handleClick(event) {
+    const button = event.target?.closest?.("[data-action]");
+    if (!button) {
+      return;
+    }
+
+    const action = button.dataset.action;
+    const id = button.dataset.id ?? "";
+    const index = Number(button.dataset.index);
+    const category = button.dataset.category ?? "";
+    const amount = Number(button.dataset.amount ?? NaN);
+
+    switch (action) {
+      case "clear-search":
+        app.runtime.routeQuery = "";
+        break;
+      case "move-stop-up":
+        if (Number.isInteger(index)) {
+          app.runtime.route.stops = reorderStops(app.runtime.route.stops, index, Math.max(0, index - 1));
+        }
+        break;
+      case "move-stop-down":
+        if (Number.isInteger(index)) {
+          app.runtime.route.stops = reorderStops(app.runtime.route.stops, index, Math.min(app.runtime.route.stops.length - 1, index + 1));
+        }
+        break;
+      case "remove-stop":
+        if (id) {
+          app.runtime.route.stops = removeStop(app.runtime.route.stops, id);
+        }
+        break;
+      case "toggle-activity":
+        if (Number.isInteger(index)) {
+          toggleActivityStatus(app.runtime.route.agenda, index);
+        }
+        break;
+      case "remove-activity":
+        if (Number.isInteger(index)) {
+          removeActivity(app.runtime.route.agenda, index);
+        }
+        break;
+      case "remove-note":
+        if (id) {
+          removeNote(id);
+          syncMemoriesSnapshot(app);
+        }
+        break;
+      case "remove-favorite":
+        if (id) {
+          removeFavorite({ id });
+          syncMemoriesSnapshot(app);
+        }
+        break;
+      case "toggle-packing":
+        if (id) {
+          app.runtime.organization.togglePackingItem(id);
+        }
+        break;
+      case "remove-packing":
+        if (id) {
+          app.runtime.organization.removePackingItem(id);
+        }
+        break;
+      case "remove-expense":
+        if (category && Number.isFinite(amount)) {
+          app.runtime.organization.removeExpense(category, amount);
+        }
+        break;
+      default:
+        return;
+    }
+
+    persistAndRender(app);
+  }
+
+  render();
+
+  if (app.root && typeof app.root.addEventListener === "function") {
+    app.root.addEventListener("submit", (event) => {
+      if (event.target instanceof HTMLFormElement) {
+        event.preventDefault();
+        handleSubmit(event);
+      }
+    });
+    app.root.addEventListener("click", (event) => {
+      const target = event.target;
+      if (target instanceof Element && target.matches("button, input[type='checkbox']")) {
+        if (target.matches("input[type='checkbox'][data-action='toggle-packing']")) {
+          handleClick({ target });
+          return;
+        }
+
+        if (target.closest("[data-action]")) {
+          handleClick({ target });
+        }
+      }
+    });
+  }
+
+  return {
+    runtime,
+    render,
+    persist() {
+      persistAndRender(app);
+    },
+  };
+}
+
+export function loadDashboardSnapshotFromStorage(storage = globalThis.localStorage) {
+  return loadDashboardSnapshot(storage);
+}
