+                    <span>${escapeHTML(category.category)}</span>
+                    <strong>${escapeHTML(formatCurrency(category.spent))}</strong>
+                    <small>${escapeHTML(formatCurrency(category.available))} libres</small>
+                  </article>
+                `).join("")}
+              </div>
+              <form class="card-form" data-action="set-budget">
+                <h3>Actualizar presupuesto</h3>
+                <label>
+                  <span>Total</span>
+                  <input name="total" type="number" min="0" step="1" placeholder="320000" />
+                </label>
+                <button type="submit">Guardar presupuesto</button>
+              </form>
+              <form class="card-form" data-action="add-expense">
+                <h3>Agregar gasto</h3>
+                <label>
+                  <span>Categoría</span>
+                  <input name="category" type="text" placeholder="comida" required />
+                </label>
+                <label>
