+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), var(--accent-2));
+}
+
+.card-form {
+  display: grid;
+  gap: 12px;
+  padding: 16px;
+}
+
+.card-form h3 {
+  margin-bottom: 4px;
+}
+
+label {
+  display: grid;
+  gap: 6px;
+  font-size: 0.95rem;
+}
+
+input,
+select,
+textarea,
+button {
+  font: inherit;
+}
+
+input,
+select,
+textarea {
+  width: 100%;
+  padding: 12px 13px;
+  border: 1px solid rgba(61, 49, 40, 0.18);
+  border-radius: var(--radius-sm);
+  background: rgba(255, 255, 255, 0.9);
+  color: var(--text);
+}
+
+input:focus,
+select:focus,
+textarea:focus,
+button:focus-visible {
+  outline: 3px solid rgba(38, 93, 114, 0.32);
+  outline-offset: 2px;
+}
+
+button {
+  border: 0;
+  border-radius: var(--radius-sm);
+  padding: 11px 15px;
+  background: var(--accent);
+  color: #fff;
+  cursor: pointer;
+  transition: transform 120ms ease, box-shadow 120ms ease, background 120ms ease;
+  box-shadow: 0 12px 26px rgba(141, 91, 45, 0.2);
+}
+
+button:hover {
+  transform: translateY(-1px);
+}
+
+.ghost-button,
+.danger-button {
+  padding: 9px 12px;
+  background: transparent;
+  color: var(--text);
+  box-shadow: none;
+  border: 1px solid rgba(61, 49, 40, 0.14);
+}
+
+.danger-button {
+  border-color: rgba(175, 54, 35, 0.2);
+  color: #932c1a;
+}
+
+.inline-form {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  align-items: center;
+}
+
+.inline-form input {
+  min-width: min(100%, 280px);
+}
+
+.inline-form button,
+.card-form button {
+  align-self: start;
+}
+
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+@media (min-width: 1100px) {
+  .dashboard-grid {
+    grid-template-columns: repeat(12, minmax(0, 1fr));
+  }
+
+  .panel--route {
+    grid-column: span 12;
+  }
+
+  .panel--organization {
+    grid-column: span 7;
+  }
+
+  .panel--memories {
+    grid-column: span 5;
+  }
+}
+
+@media (max-width: 1099px) {
+  .hero {
+    grid-template-columns: 1fr;
+  }
+
+  .summary-grid,
+  .split-list {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 720px) {
+  .app-shell {
+    width: min(100vw - 18px, 100%);
+    padding: 12px 0 24px;
+  }
+
+  .hero__metrics {
+    grid-template-columns: 1fr 1fr;
+  }
+
+  .item-card,
+  .item-row {
+    flex-direction: column;
+  }
+
+  .item-card__actions,
+  .item-row__side {
+    justify-content: flex-start;
+  }
+}
+
