+  updateStop,
+} from "../js/route/integration/index.mjs";
+import { crearAgendaDiaria } from "../js/route/agenda/agenda.mjs";
+
+export const STORAGE_KEY = "viaje-en-familia.dashboard.v1";
+
+function clone(value) {
+  if (typeof structuredClone === "function") {
+    return structuredClone(value);
+  }
+
+  return JSON.parse(JSON.stringify(value));
+}
+
+function isoDate(value = new Date()) {
+  return value instanceof Date ? value.toISOString() : new Date(value).toISOString();
+}
+
+function escapeHTML(value) {
+  return String(value ?? "")
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;");
+}
+
+function formatCurrency(amount) {
+  return new Intl.NumberFormat("es-AR", {
+    style: "currency",
+    currency: "ARS",
+    maximumFractionDigits: 0,
+  }).format(amount);
+}
+
+function formatPercent(value) {
+  return `${value}%`;
+}
+
+function defaultSeed() {
+  const stops = [];
+  createStop(stops, {
+    id: "stop-salida",
+    name: "Salida",
+    dates: ["Día 1", "Día 2"],
+    description: "Llegada, descanso y primer ajuste del viaje.",
+  });
+  createStop(stops, {
+    id: "stop-costa",
+    name: "Costa",
+    dates: ["Día 3", "Día 4"],
+    description: "Playas, comidas simples y tiempos libres.",
+  });
+  createStop(stops, {
+    id: "stop-regreso",
+    name: "Regreso",
+    dates: ["Día 5"],
+    description: "Cierre del itinerario y vuelta a casa.",
+  });
+
+  const agenda = crearAgendaDiaria([
+    { dia: "Día 1", parada: "Salida", horario: "08:00", estado: "pendiente" },
+    { dia: "Día 3", parada: "Costa", horario: "11:30", estado: "pendiente" },
+    { dia: "Día 5", parada: "Regreso", horario: "16:00", estado: "completada" },
+  ]);
+
+  const organization = createOrganizationIntegration({
+    budget: {
+      total: 320000,
+      categories: {
+        alojamiento: { budget: 140000 },
+        comida: { budget: 90000 },
+        transporte: { budget: 60000 },
+      },
+    },
+  });
+
+  organization
+    .addExpense("alojamiento", 84000)
+    .addExpense("comida", 26000)
+    .addExpense("transporte", 18000)
+    .addPackingItem({ id: "pasaportes", label: "Pasaportes" })
+    .addPackingItem({ id: "cargadores", label: "Cargadores", packed: true })
+    .addPackingItem({ id: "botiquin", label: "Botiquín" });
+
+  return {
+    title: "Dashboard del viaje",
+    subtitle: "Una sola pantalla para la ruta, la organización y los recuerdos.",
+    updatedAt: isoDate(),
+    routeQuery: "",
+    route: {
+      stops,
+      activities: agenda.listarActividades(),
+    },
+    organization: organization.state,
+    memories: {
+      notes: [
+        { id: "note-1", stopId: "stop-salida", text: "Confirmar check-in temprano." },
+        { id: "note-2", stopId: "stop-costa", text: "Llevar protector solar y agua extra." },
+      ],
+      favorites: [
+        { id: "mirador", refId: "stop-costa", refType: "stop", label: "Mirador de la costa" },
+      ],
+    },
+  };
+}
+
+function normalizeArray(value, fallback = []) {
+  return Array.isArray(value) ? value.map((item) => clone(item)) : clone(fallback);
+}
+
+function normalizeSnapshot(input = {}) {
+  const seed = defaultSeed();
+  const route = input.route && typeof input.route === "object" ? input.route : {};
+  const memories = input.memories && typeof input.memories === "object" ? input.memories : {};
+
+  return {
+    title: typeof input.title === "string" && input.title.trim() ? input.title.trim() : seed.title,
+    subtitle: typeof input.subtitle === "string" && input.subtitle.trim() ? input.subtitle.trim() : seed.subtitle,
+    updatedAt: typeof input.updatedAt === "string" && input.updatedAt.trim() ? input.updatedAt : seed.updatedAt,
+    routeQuery: typeof input.routeQuery === "string" ? input.routeQuery : "",
+    route: {
+      stops: normalizeArray(route.stops, seed.route.stops),
+      activities: normalizeArray(route.activities, seed.route.activities),
+    },
+    organization: input.organization && typeof input.organization === "object" ? clone(input.organization) : clone(seed.organization),
+    memories: {
+      notes: normalizeArray(memories.notes, seed.memories.notes),
+      favorites: normalizeArray(memories.favorites, seed.memories.favorites),
+    },
+  };
+}
+
+function loadJSON(storage, key) {
+  if (!storage || typeof storage.getItem !== "function") {
+    return null;
+  }
+
+  try {
+    const raw = storage.getItem(key);
+    if (!raw) {
+      return null;
+    }
+
+    return JSON.parse(raw);
+  } catch {
+    return null;
+  }
+}
+
+export function createDashboardSnapshot(input = {}) {
+  return normalizeSnapshot(input);
+}
+
+export function loadDashboardSnapshot(storage = globalThis.localStorage) {
+  const stored = loadJSON(storage, STORAGE_KEY);
+  return normalizeSnapshot(stored ?? defaultSeed());
+}
+
+export function saveDashboardSnapshot(snapshot, storage = globalThis.localStorage) {
+  if (!storage || typeof storage.setItem !== "function") {
+    return snapshot;
+  }
+
+  storage.setItem(STORAGE_KEY, JSON.stringify(snapshot));
+  return snapshot;
+}
+
+function syncMemories(snapshot) {
+  resetMemories();
+  for (const note of snapshot.memories.notes) {
+    addNote(note);
+  }
+  for (const favorite of snapshot.memories.favorites) {
+    addFavorite(favorite);
+  }
+}
+
+function createRuntime(snapshot = loadDashboardSnapshot()) {
+  const normalized = normalizeSnapshot(snapshot);
+  const organization = createOrganizationIntegration(normalized.organization);
+
+  syncMemories(normalized);
+
+  return {
+    title: normalized.title,
+    subtitle: normalized.subtitle,
+    updatedAt: normalized.updatedAt,
+    routeQuery: normalized.routeQuery,
+    route: {
+      stops: normalized.route.stops,
+      agenda: crearAgendaDiaria(normalized.route.activities),
+    },
+    organization,
+    memories: {
+      notes: listNotes(),
+      favorites: listFavorites(),
+    },
+  };
+}
+
