index 0000000000000000000000000000000000000000..3f52677dfe54ef59b3f4cabbbec2f3370e0096ef
--- /dev/null
+++ b/public/app/dashboard.test.mjs
@@ -0,0 +1,126 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  createDashboardApp,
+  createDashboardSnapshot,
+  loadDashboardSnapshot,
+  renderDashboardHTML,
+  saveDashboardSnapshot,
+  STORAGE_KEY,
+} from "./dashboard.mjs";
+
+function createMemoryStorage(initial = {}) {
+  const store = new Map(Object.entries(initial));
+
+  return {
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    dump() {
+      return Object.fromEntries(store.entries());
+    },
+  };
+}
+
+test("dashboard snapshot seeds the three areas and round-trips through storage", () => {
+  const storage = createMemoryStorage();
+  const snapshot = createDashboardSnapshot();
+
+  assert.ok(snapshot.route.stops.length >= 3);
+  assert.ok(snapshot.organization.packing.items.length >= 3);
+  assert.ok(snapshot.memories.notes.length >= 2);
+
+  saveDashboardSnapshot(snapshot, storage);
+
+  const stored = storage.getItem(STORAGE_KEY);
+  assert.ok(stored);
+
+  const reloaded = loadDashboardSnapshot(storage);
+  assert.equal(reloaded.title, snapshot.title);
+  assert.equal(reloaded.route.stops.length, snapshot.route.stops.length);
+  assert.equal(reloaded.organization.packing.items.length, snapshot.organization.packing.items.length);
+  assert.equal(reloaded.memories.favorites.length, snapshot.memories.favorites.length);
+});
+
+test("renderDashboardHTML integrates the three areas in a single accessible shell", () => {
+  const snapshot = createDashboardSnapshot({
+    title: "Prueba de tablero",
+    routeQuery: "costa",
+  });
+  const html = renderDashboardHTML({
+    ...snapshot,
+    route: {
+      stops: snapshot.route.stops,
+      agenda: {
+        listarActividades() {
+          return snapshot.route.activities;
+        },
+      },
+    },
+    organization: {
+      getBudgetSummary() {
+        return {
+          total: 100,
+          spent: 20,
+          available: 80,
+          categories: [
+            { category: "comida", budget: 50, spent: 20, available: 30 },
+          ],
+        };
+      },
+      getPackingProgress() {
+        return { completed: 1, remaining: 0, total: 1, percentage: 100 };
+      },
+      state: {
+        packing: {
+          items: [{ id: "bag", label: "Mochila", packed: true }],
+        },
+      },
+    },
+    memories: {
+      notes: snapshot.memories.notes,
+      favorites: snapshot.memories.favorites,
+    },
+  });
+
+  assert.match(html, /Plan del recorrido/);
+  assert.match(html, /Presupuesto y equipaje/);
+  assert.match(html, /Notas y favoritos/);
+  assert.match(html, /aria-label="Resumen general"/);
+});
+
+test("createDashboardApp renders into a root and persists the latest snapshot", () => {
+  const storage = createMemoryStorage();
+  const root = {
+    innerHTML: "",
+    addEventListener() {},
+  };
+
+  const app = createDashboardApp({
+    root,
+    storage,
+    snapshot: createDashboardSnapshot({
+      title: "Tablero persistente",
+      routeQuery: "costa",
+    }),
+  });
+
+  assert.match(root.innerHTML, /Tablero persistente/);
+  assert.match(root.innerHTML, /Ruta/);
+  assert.match(root.innerHTML, /Organización/);
+  assert.match(root.innerHTML, /Recuerdos/);
+
+  app.persist();
+
+  const saved = JSON.parse(storage.getItem(STORAGE_KEY));
+  assert.equal(saved.title, "Tablero persistente");
+  assert.equal(saved.routeQuery, "costa");
+});
+
