import { stat } from "node:fs/promises";
import { createServer } from "node:http";
import path from "node:path";

const host = process.env.HOST ?? "127.0.0.1";
const port = Number(process.env.PORT ?? 4173);
const publicRoot = path.resolve("public");

const contentTypes = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml"
};

createServer(async (request, response) => {
  try {
    const pathname = decodeURIComponent(new URL(request.url ?? "/", "http://localhost").pathname);
    const relative = pathname === "/" ? "app/index.html" : pathname.replace(/^\/+/, "");
    let candidate = path.resolve(publicRoot, relative);
    if (candidate !== publicRoot && !candidate.startsWith(publicRoot + path.sep)) {
      response.writeHead(403).end("Forbidden");
      return;
    }
    let info = await stat(candidate);
    if (info.isDirectory()) {
      candidate = path.resolve(candidate, "index.html");
      if (candidate !== publicRoot && !candidate.startsWith(publicRoot + path.sep)) {
        response.writeHead(403).end("Forbidden");
        return;
      }
      info = await stat(candidate);
    }
    if (!info.isFile()) throw Object.assign(new Error("Not a file"), { code: "ENOENT" });
    response.writeHead(200, {
      "content-type": contentTypes[path.extname(candidate)] ?? "application/octet-stream",
      "cache-control": "no-store"
    });
    createReadStream(candidate).pipe(response);
  } catch (error) {
    response.writeHead(error?.code === "ENOENT" ? 404 : 500, { "content-type": "text/plain; charset=utf-8" });
    response.end(error?.code === "ENOENT" ? "Not found" : "Internal server error");
  }
}).listen(port, host, () => {
  console.log(`Viaje en Familia available at http://${host}:${port}`);
});


