diff --git a/public/app/styles.css b/public/app/styles.css
new file mode 100644
index 0000000000000000000000000000000000000000..7be6292117de711bd13053cb83cfd9a099b49ac4
--- /dev/null
+++ b/public/app/styles.css
@@ -0,0 +1,425 @@
+:root {
+  color-scheme: light;
+  --bg: #f4efe8;
+  --bg-alt: #ece4da;
+  --surface: rgba(255, 255, 255, 0.8);
+  --surface-strong: #fffaf4;
+  --text: #1d1a17;
+  --muted: #6d6259;
+  --accent: #8d5b2d;
+  --accent-2: #265d72;
+  --line: rgba(61, 49, 40, 0.14);
+  --shadow: 0 18px 50px rgba(42, 29, 19, 0.12);
+  --radius-xl: 28px;
+  --radius-lg: 20px;
+  --radius-md: 14px;
+  --radius-sm: 10px;
+  font-family: Inter, "Segoe UI", system-ui, sans-serif;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html,
+body {
+  min-height: 100%;
+}
+
+body {
+  margin: 0;
+  color: var(--text);
+  background:
+    radial-gradient(circle at top left, rgba(141, 91, 45, 0.18), transparent 28%),
+    radial-gradient(circle at 90% 0%, rgba(38, 93, 114, 0.18), transparent 24%),
+    linear-gradient(180deg, var(--bg), var(--bg-alt));
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background-image:
+    linear-gradient(rgba(255, 255, 255, 0.22) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(255, 255, 255, 0.18) 1px, transparent 1px);
+  background-size: 44px 44px;
+  opacity: 0.3;
+  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.5), transparent 85%);
+}
+
+.app-root {
+  position: relative;
+  z-index: 1;
+}
+
+.app-shell {
+  width: min(1440px, calc(100vw - 32px));
+  margin: 0 auto;
+  padding: 28px 0 40px;
+}
+
+.hero {
+  display: grid;
+  grid-template-columns: minmax(0, 1.2fr) minmax(320px, 0.8fr);
+  gap: 20px;
+  align-items: end;
+  margin-bottom: 22px;
+}
+
+.hero__copy,
+.metric,
+.panel,
+.summary-card,
+.progress-card {
+  backdrop-filter: blur(14px);
+}
+
+.hero__copy {
+  padding: 24px 26px;
+  border: 1px solid var(--line);
+  border-radius: var(--radius-xl);
+  background: linear-gradient(145deg, rgba(255, 250, 244, 0.94), rgba(255, 255, 255, 0.75));
+  box-shadow: var(--shadow);
+}
+
+.eyebrow {
+  margin: 0 0 8px;
+  font-size: 0.78rem;
+  letter-spacing: 0.22em;
+  text-transform: uppercase;
+  color: var(--accent-2);
+}
+
+h1,
+h2,
+h3,
+p {
+  margin-top: 0;
+}
+
+h1 {
+  margin-bottom: 10px;
+  font-size: clamp(2rem, 4vw, 3.8rem);
+  line-height: 0.95;
+  letter-spacing: -0.04em;
+}
+
+.lead {
+  margin-bottom: 0;
+  max-width: 62ch;
+  color: var(--muted);
+  font-size: 1.03rem;
+}
+
+.hero__metrics {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 14px;
+}
+
+.metric {
+  padding: 18px;
+  border: 1px solid var(--line);
+  border-radius: var(--radius-lg);
+  background: linear-gradient(180deg, rgba(255, 255, 255, 0.84), rgba(247, 240, 232, 0.82));
+  box-shadow: var(--shadow);
+}
+
+.metric span,
+.metric small,
+.item-card__meta,
+.item-row p {
+  color: var(--muted);
+}
+
+.metric strong {
+  display: block;
+  margin: 6px 0 4px;
+  font-size: 1.5rem;
+  letter-spacing: -0.03em;
+}
+
+.dashboard-grid {
+  display: grid;
+  grid-template-columns: 1fr;
+  gap: 18px;
+}
+
+.panel {
+  border: 1px solid var(--line);
+  border-radius: var(--radius-xl);
+  background: var(--surface);
+  box-shadow: var(--shadow);
+  overflow: hidden;
+}
+
+.panel__header,
+.panel__body {
+  padding: 20px;
+}
+
+.panel__header {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: space-between;
+  gap: 14px;
+  align-items: center;
+  border-bottom: 1px solid var(--line);
+  background: linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(255, 255, 255, 0.35));
+}
+
+.panel__header h2 {
+  margin-bottom: 0;
+  font-size: 1.45rem;
+}
+
+.panel__body {
+  display: grid;
+  gap: 18px;
+}
+
+.split-list {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 16px;
+}
+
+.stack {
+  display: grid;
+  gap: 16px;
+}
+
+.item-list {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+  display: grid;
+  gap: 12px;
+}
+
+.item-card,
+.item-row,
+.summary-card,
+.progress-card,
+.card-form {
+  border: 1px solid var(--line);
+  border-radius: var(--radius-md);
+  background: var(--surface-strong);
+}
+
+.item-card,
+.item-row {
+  display: flex;
+  justify-content: space-between;
+  gap: 14px;
+  padding: 14px;
+}
+
+.item-card__content p,
+.item-row p {
+  margin-bottom: 0;
+}
+
+.item-card--done {
+  border-color: rgba(38, 93, 114, 0.24);
+}
+
+.item-card__title-row {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px 12px;
+  align-items: baseline;
+}
+
+.item-card__actions,
+.item-row__side {
+  display: flex;
+  gap: 8px;
+  align-items: center;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+  white-space: nowrap;
+}
+
+.summary-grid {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.summary-card,
+.progress-card {
+  padding: 16px;
+}
+
+.summary-card strong,
+.progress-card h3 {
+  display: block;
+  margin: 8px 0 4px;
+  font-size: 1.3rem;
+}
+
+.progress-bar {
+  height: 12px;
+  background: rgba(141, 91, 45, 0.12);
+  border-radius: 999px;
+  overflow: hidden;
+}
+
+.progress-bar span {
+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), var(--accent-2));
+}
+
+.card-form {
+  display: grid;
+  gap: 12px;
+  padding: 16px;
+}
+
+.card-form h3 {
+  margin-bottom: 4px;
+}
+
+label {
+  display: grid;
+  gap: 6px;
+  font-size: 0.95rem;
+}
+
+input,
+select,
+textarea,
+button {
+  font: inherit;
+}
+
+input,
+select,
+textarea {
+  width: 100%;
+  padding: 12px 13px;
+  border: 1px solid rgba(61, 49, 40, 0.18);
+  border-radius: var(--radius-sm);
+  background: rgba(255, 255, 255, 0.9);
+  color: var(--text);
+}
+
+input:focus,
+select:focus,
+textarea:focus,
+button:focus-visible {
+  outline: 3px solid rgba(38, 93, 114, 0.32);
+  outline-offset: 2px;
+}
+
+button {
+  border: 0;
+  border-radius: var(--radius-sm);
+  padding: 11px 15px;
+  background: var(--accent);
+  color: #fff;
+  cursor: pointer;
+  transition: transform 120ms ease, box-shadow 120ms ease, background 120ms ease;
+  box-shadow: 0 12px 26px rgba(141, 91, 45, 0.2);
+}
+
+button:hover {
+  transform: translateY(-1px);
+}
+
+.ghost-button,
+.danger-button {
+  padding: 9px 12px;
+  background: transparent;
+  color: var(--text);
+  box-shadow: none;
+  border: 1px solid rgba(61, 49, 40, 0.14);
+}
+
+.danger-button {
+  border-color: rgba(175, 54, 35, 0.2);
+  color: #932c1a;
+}
+
+.inline-form {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  align-items: center;
+}
+
+.inline-form input {
+  min-width: min(100%, 280px);
+}
+
+.inline-form button,
+.card-form button {
+  align-self: start;
+}
+
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+@media (min-width: 1100px) {
+  .dashboard-grid {
+    grid-template-columns: repeat(12, minmax(0, 1fr));
+  }
+
+  .panel--route {
+    grid-column: span 12;
+  }
+
+  .panel--organization {
+    grid-column: span 7;
+  }
+
+  .panel--memories {
+    grid-column: span 5;
+  }
+}
+
+@media (max-width: 1099px) {
+  .hero {
+    grid-template-columns: 1fr;
+  }
+
+  .summary-grid,
+  .split-list {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 720px) {
+  .app-shell {
+    width: min(100vw - 18px, 100%);
+    padding: 12px 0 24px;
+  }
+
+  .hero__metrics {
+    grid-template-columns: 1fr 1fr;
+  }
+
+  .item-card,
+  .item-row {
+    flex-direction: column;
+  }
+
+  .item-card__actions,
+  .item-row__side {
+    justify-content: flex-start;
+  }
+}
+
